# ---------------------------------------------------------------- instruments
IN = {'KICK':1,'SNARE':2,'HATC':3,'HATO':4,'CRASH':5,'TOM':6,'BASS':7,'ARP':8,
      'PAD':9,'LEAD':10,'SWEEP':11,'SUB':12,'STAB':13}
SAMPLES = [  # (instr, wav file, header volume, panning, loop:None or (start,len))
    ('KICK',  'kick',  50, 128, None),
    ('SNARE', 'snare', 46, 128, None),
    ('HATC',  'hatc',  30, 112, None),
    ('HATO',  'hato',  26, 140, None),
    ('CRASH', 'crash', 26, 128, None),
    ('TOM',   'tom',   40, 118, None),
    ('BASS',  'bass',  42, 128, (0, 4410)),
    ('ARP',   'arp',   28, 152, (0, 22050)),
    ('PAD',   'pad',   26, 104, (0, 44100)),
    ('LEAD',  'lead',  42, 128, (0, 22050)),
    ('SWEEP', 'sweep', 22, 128, None),
