M5 = [('A4',2),('E5',2),('A5',2),('G5',2),('E5',4),('C5',4),
      ('A4',2),('F5',2),('A5',2),('G5',2),('F5',4),('C5',4),
      ('G4',2),('E5',2),('G5',2),('E5',2),('C6',4),('G5',4),
