                for r in (2, 6, 10, 14): add(p, b0+r, CH['HAT'], IN['HATC'], 61, 34)
                add(p, b0+12, CH['SNARE'], IN['SNARE'], 61, 46)
            elif bar == 2:
                drum_kick(p, 0, 2, sec, [0, 4, 8, 12])
                for r in (2, 6, 10, 14): add(p, b0+r, CH['HAT'], IN['HATC'], 61, 36)
                for r in (4, 12): add(p, b0+r, CH['SNARE'], IN['SNARE'], 61, 52)
