                drum_kick(p, 0, bar, sec, kicks)
                for r in (2, 6, 10, 14):
                    add(p, b0+r, CH['HAT'], IN['HATC'], 61, 42 if r % 8 == 2 else 36)
                for r in (4, 12): add(p, b0+r, CH['SNARE'], IN['SNARE'], 61, 58)
                if bar in (1, 3):
                    add(p, b0+6, CH['HAT'], IN['HATO'], 61, 30)
                if bar == 3:
                    for i, r in enumerate((60, 61, 62, 63)):
                        add(p, r, CH['PERC'], IN['TOM'], 64-2*i, 50+4*i)
            elif sec == 'a2':
                kicks = [0, 3, 4, 8, 11, 12]
                drum_kick(p, 0, bar, sec, kicks)
                for r in (2, 6, 10, 14):
                    add(p, b0+r, CH['HAT'], IN['HATC'], 61, 42 if r % 8 == 2 else 36)
                for r in (4, 12): add(p, b0+r, CH['SNARE'], IN['SNARE'], 61, 58)
                if bar == 3:
                    for i, r in enumerate((60, 61, 62, 63)):
                        add(p, r, CH['PERC'], IN['TOM'], 64-2*i, 50+4*i)
            elif sec in ('b', 'b2'):
                kicks = [0, 3, 4, 8, 11, 12] + ([14] if bar == 3 else [])
                drum_kick(p, 0, bar, sec, kicks)
                for r in (2, 6, 10, 14):
                    add(p, b0+r, CH['HAT'], IN['HATC'], 61, 42 if r % 8 == 2 else 36)
                if bar == 3:
                    for r in (13, 15): add(p, b0+r, CH['HAT'], IN['HATC'], 61, 26)
                for r in (4, 12): add(p, b0+r, CH['SNARE'], IN['SNARE'], 61, 58)
                if bar == 3 and sec == 'b2':
                    for i, r in enumerate((60, 61, 62, 63)):
                        add(p, r, CH['PERC'], IN['TOM'], 64-2*i, 50+4*i)
            elif sec == 'break':
                if bar == 0:
                    add(p, b0+8, CH['HAT'], IN['HATC'], 61, 22)
                elif bar == 1:
                    for r in (0, 4, 8, 12): add(p, b0+r, CH['HAT'], IN['HATC'], 61, 28)
                elif bar == 2:
