                    add(p, b0+0, CH['KICK'], IN['KICK'], 61, 60)
                    add(p, b0+8, CH['KICK'], IN['KICK'], 61, 60)
            elif sec == 'climax':
                kicks = [0, 4, 8, 12] + ([6, 14] if bar in (1, 3) else [])
                drum_kick(p, 0, bar, sec, kicks)
                for r in range(16):
                    if r in (0, 4, 8, 12): continue
                    v = 42 if r % 4 == 2 else (34 if r % 2 == 0 else 26)
                    add(p, b0+r, CH['HAT'], IN['HATC'], 61, v)
                for r in (4, 12): add(p, b0+r, CH['SNARE'], IN['SNARE'], 61, 60)
                if bar in (0, 2):
                    add(p, b0+2, CH['HAT'], IN['HATO'], 61, 30)
