# ---------------------------------------------------------------- cell store
pats = [dict() for _ in range(NPAT)]     # pattern -> {(row,ch): cell}
def add(p, row, ch, inst=None, note=None, vol=None, fx=None, param=None):
    if not (0 <= row < ROWS):
        return
    pats[p][(row, ch)] = dict(inst=inst, note=note, vol=vol, fx=fx, param=param)
def off(p, row, ch):
    if 0 <= row < ROWS:
