def part_bass(p, sec, prog):
    for bar, cn in enumerate(prog):
        b0 = bar*16
        root = CHORDS[cn]['bass'] if cn in CHORDS else CHX[cn]['bass']
        kickrows = [0, 4, 8, 12]
