            arpp = 0x37 if MAJ[cn] == 0 else 0x47
            for r in (0, 4, 8, 12):
                add(p, b0+r, CH['ARP'], IN['ARP'], tones[0], 52, fx=0, param=arpp)
            continue
        order = [0, 1, 2, 3, 2, 1]
        for r in range(16):
            idx = order[r % 6] if r % 16 < 12 else order[(r - 12) % 4]
            v = (50 if r % 4 == 0 else 40) + (2 if bar >= 2 else 0)
            v = int(round(v * pump_factor(kickrows, r)))
            add(p, b0+r, CH['ARP'], IN['ARP'], tones[idx], v)

def part_pad(p, sec, prog, table):
    for bar, cn in enumerate(prog):
        b0 = bar*16
        root = table[cn]['pad']
        if sec == 'intro' and bar == 0:
            continue
        vol = 50 if sec == 'break' else 46
        add(p, b0, CH['PAD'], IN['PAD'], tn('PAD', root), vol)
        if sec not in ('break',):
            kickrows = [0, 4, 8, 12]
            for r in (4, 8, 12):
                v = int(round(vol * pump_factor(kickrows, r)))
                add(p, b0+r, CH['PAD'], vol=v)

def part_extra(p, sec, prog, table):
    if sec in ('intro', 'break'):
        add(p, 32, CH['XTRA'], IN['SWEEP'], 61, 52)
    if sec in ('a', 'a_full'):
        add(p, 0, CH['XTRA'], IN['STAB'], tn('STAB', table[prog[0]]['stab']), 46)
    if sec in ('b', 'b2'):
        add(p, 0, CH['XTRA'], IN['STAB'], tn('STAB', table[prog[0]]['stab']), 40)
    if sec == 'climax':
        for bar, cn in enumerate(prog):
            b0 = bar*16
            add(p, b0+0,  CH['XTRA'], IN['STAB'], tn('STAB', table[cn]['stab']), 44)
            add(p, b0+8,  CH['XTRA'], IN['STAB'], tn('STAB', table[cn]['stab']), 34)

SEC = {0:'intro',1:'a',2:'a',3:'a2',4:'b',5:'break',6:'a_full',7:'b2',8:'climax',9:'outro'}

def build():
    for p in range(NPAT):
        sec = SEC[p]
        prog = PROG[p]
        table = CHX if sec == 'climax' else CHORDS
        part_drums(p, sec)
        part_bass(p, sec, prog)
        part_arp(p, sec, prog, table)
        part_pad(p, sec, prog, table)
        part_extra(p, sec, prog, table)
        if p in LEADS:
            lead_place(p, LEADS[p], vol_base=60 if sec in ('climax',) else 56)
            ec = ECHO.get(p)
            if ec:
                echo_place(p, LEADS[p], *ec)
    # outro: stop lead + echo tails at the end
    off(9, 60, CH['LEAD']); off(9, 62, CH['ECHO'])
    # lead must not ring into P1 at the loop point
    off(2, 64-1, CH['LEAD']) if False else None
    return pats

def melody_len(mel):
    return sum(d for _, d in mel)

if __name__ == '__main__':
    pats = build()
