import compose as C
pats_starts={2:11.4286,3:17.1429,4:22.8571,5:28.5714,6:34.2857,7:40.0,8:45.7143}
for p,t0 in pats_starts.items():
    mel=C.LEADS[p]
    row=0.0892857; r=0; res=[]
    for nm,d in mel:
        a=int((t0+r*row+0.015)*sr); b=int((t0+r*row+min(d,2)*row-0.015)*sr)
        seg=m[a:b]
        X=np.abs(np.fft.rfft(seg*np.hanning(len(seg)))); f=np.fft.rfftfreq(len(seg),1/sr)
        ef=freq(nm); band=(f>ef*0.82)&(f<ef*1.22); i=np.argmin(abs(f-ef))
